import { API_BASE_URL } from './config.js';

const simulationDate = null; // 例：'2025-08-17'，歷史查詢時給日期，否則 null

async function fetchHoldings(simulationDate = null) {
    let url;
    if (simulationDate) {
        url = `${API_BASE_URL}/holdings/history?date=${simulationDate}`;
    } else {
        url = `${API_BASE_URL}/holdings/live`;
    }
    try {
        const res = await fetch(url);
        if (!res.ok) throw new Error('API 請求失敗');
        const result = await res.json();
        if (!result.ok) throw new Error(result.error || 'API 回傳錯誤');
        return result.data;
    } catch (err) {
        console.error('庫存明細查詢失敗:', err);
        return [];
    }
}

function renderHoldings(holdings, simulationDate) {
	const table = document.querySelector('.table.table-bordered');
	const theadTr = table.querySelector('thead tr');
	const tbody = table.querySelector('tbody');
	// 動態插入模擬日期欄位
	if (simulationDate) {
		if (!theadTr.querySelector('.sim-date-th')) {
			const th = document.createElement('th');
			th.textContent = '模擬日期';
			th.className = 'sim-date-th';
			theadTr.insertBefore(th, theadTr.firstChild);
		}
	} else {
		const th = theadTr.querySelector('.sim-date-th');
		if (th) th.remove();
	}
	tbody.innerHTML = '';
	holdings.forEach(h => {
		const tr = document.createElement('tr');
		let row = '';
		if (simulationDate) row += `<td>${simulationDate}</td>`;
		row += `
			<td>${h.symbol}</td>
			<td>${h.name}</td>
			<td>-</td>
			<td>${h.holding_type || '-'}</td>
			<td>${h.estimated_profit !== undefined ? (h.estimated_profit > 0 ? '+' : '') + h.estimated_profit : '-'}</td>
			<td>${h.return_rate || '-'}</td>
			<td><button class="btn btn-sm btn-primary btn-close-position">平倉</button></td>
			<td>${h.total_quantity} / ${h.available_quantity}</td>
			<td>${h.avg_price}</td>
			<td>${h.current_price !== null && h.current_price !== undefined ? h.current_price : '-'}</td>
		`;
		tr.innerHTML = row;
		tbody.appendChild(tr);
	});
}

window.addEventListener('DOMContentLoaded', async () => {
    const holdings = await fetchHoldings(simulationDate);
	renderHoldings(holdings, simulationDate);
});
